import fs from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {fileURLToPath,pathToFileURL} from 'node:url';
import * as engine from '../lib/engine.mjs';
import {validateContract} from '../lib/contract.mjs';
import {contained, digest, safeId} from '../lib/files.mjs';
import {runProcess} from '../lib/process.mjs';
import {previewInstall,applyInstall,rollbackInstall,defaultRule} from '../lib/install.mjs';
import childProcess from 'node:child_process';
import {syncBuiltinESMExports} from 'node:module';
import {EventEmitter} from 'node:events';
import {checkHarnessPaths} from '../check-harness-paths.mjs';

const option=process.argv.indexOf('--work-root');
if(option<0||!process.argv[option+1]||!path.isAbsolute(process.argv[option+1]))throw new Error('Supply --work-root ABSOLUTE_AUTHORIZED_TEST_DIRECTORY.');
const work=path.resolve(process.argv[option+1]);await fs.mkdir(work,{recursive:true});
const source=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const cli=path.join(source,'scripts/harness.mjs');
const root=await fs.mkdtemp(path.join(work,'fixtures-'));
const results=[];const fixturePreparationRetries=[];
const prefixIndex=process.argv.indexOf('--case-prefix');const casePrefix=prefixIndex<0?null:process.argv[prefixIndex+1];if(prefixIndex>=0&&!casePrefix)throw new Error('Missing --case-prefix value.');
const writeJson=(file,value)=>fs.writeFile(file,JSON.stringify(value,null,2)+'\n');
const readJson=async file=>JSON.parse(await fs.readFile(file,'utf8'));
function command(args) {
  const r=spawnSync(process.execPath,[cli,...args],{encoding:'utf8',timeout:20000,windowsHide:true,shell:false,cwd:work});
  return {args,code:r.status,stdout:r.stdout,stderr:r.stderr,error:r.error?.message};
}
async function test(id,expected,body) {
  if(casePrefix&&!id.startsWith(casePrefix))return;
  try {const observed=await body();results.push({id,expected,pass:true,observed});}
  catch(e) {results.push({id,expected,pass:false,error:e.message,stack:e.stack?.split('\n').slice(0,4)});}
  console.log(JSON.stringify(results.at(-1)));
}
async function fixture(name,{layered=true,two=true,acceptance,templateVersion}={}) {
  const project=path.join(root,name);await fs.mkdir(project,{recursive:true});
  const id='synthetic-'+name;
  const d=await engine.draft(project,id,'SYNTHETIC TEST ONLY: exercise local harness contracts','general',layered?'layered':undefined);
  const directory=d.directory;const c=await readJson(path.join(directory,'contract.json'));
  if(templateVersion==='missing')delete c.templateVersion;else if(templateVersion!==undefined)c.templateVersion=templateVersion;
  c.inputs=[{source:'Synthetic fixture generated by this audit; no real observations or user approvals',path:'input.txt'}];
  await fs.writeFile(path.join(project,'input.txt'),'SYNTHETIC IMMUTABLE INPUT\n');
  c.deliverables=[{id:'out-a',path:'out/a.txt'},...(two?[{id:'out-b',path:'out/b.txt'}]:[])];
  c.tasks=[{id:'a',title:'Produce synthetic artifact A',dependsOn:[],outputs:['out-a'],acceptance:acceptance??[{id:'exists-a',type:'artifact',description:'Synthetic artifact A must exist'}]},...(two?[{id:'b',title:'Consume verified A and produce synthetic B',dependsOn:['a'],outputs:['out-b'],acceptance:[{id:'exists-b',type:'artifact',description:'Synthetic artifact B must exist'}]}]:[])];
  if(layered)c.contextFiles=c.tasks.map(t=>({path:`phases/${t.id}.md`,kind:'phase',tasks:[t.id],purpose:`Synthetic ${t.id} test phase`,loadWhen:`After context selects ${t.id}`}));
  await writeJson(path.join(directory,'contract.json'),c);
  if(layered) {
    const refs=command(['refs','--project',project,'--id',id]);assert.equal(refs.code,0,refs.stderr);
    const mapping=JSON.parse(refs.stdout);
    for(const doc of mapping.documents.filter(d=>d.path!=='HARNESS.md')) {
      await fs.mkdir(path.dirname(doc.file),{recursive:true});
      await fs.writeFile(doc.file,`# Synthetic fixture ${doc.path}\n\nResume with master and recovery, then context; this file is consumed only after stage selection.\n\nInput: ${doc.inputs[0].absoluteMarkdown}\n\nMethod: deterministic fixture writes in this project only. Approval records are synthetic test values, never real authorization.\n\nOutputs: ${doc.deliverables.map(d=>d.markdown).join(', ')}\n\nAcceptance: verify declared files and observed state transitions; an exception is retained as test evidence.\n\nFailure: preserve evidence and stop this synthetic branch; never alter installed skill files.\n\nHandoff: inspect current derived state before selecting dependent work.\n`);
    }
  }
  let review;
  if(layered) {
    let prepared=command(['prepare-review','--project',project,'--id',id]);
    // A definitive Windows rename denial during fresh, unreviewed fixture setup may be retried.
    // Never retry active/approved work, unknown outcomes, assertions, or injected product faults.
    for(let attempt=1;attempt<=2&&process.platform==='win32'&&Number.isInteger(prepared.code)&&prepared.code>0&&!prepared.error&&/EPERM:.*rename[\s\S]*HARNESS\.md/.test(prepared.stderr);attempt++){
      const fresh=await readJson(path.join(directory,'state.json'));
      if(fresh.phase!=='draft'||fresh.review||fresh.approval||Object.keys(fresh.tasks).length||(fresh.activeExecutions??[]).length||(fresh.executionBlockers??[]).length)break;
      fixturePreparationRetries.push({id,attempt,previous:prepared});
      await new Promise(resolve=>setTimeout(resolve,attempt*200));prepared=command(['prepare-review','--project',project,'--id',id]);
    }
    assert.equal(prepared.code,0,prepared.stderr+' '+prepared.stdout);
    const p=JSON.parse(prepared.stdout);assert.equal(p.pathCheck.ok,true);review=p.review;
  } else {await engine.render(project,id);review=await engine.prepareReview(project,id);}
  return {project,id,directory,c,review};
}
async function approve(f) {
  return engine.recordDecision(f.project,f.id,{actor:'user',decision:'approve',taskId:f.id,revision:f.c.revision,digest:f.review.digest,message:'SYNTHETIC APPROVAL FIXTURE ONLY — does not represent a real user decision.',source:'SYNTHETIC local state-machine regression under explicit authorization'});
}
async function emit(f,step,content='SYNTHETIC RESULT') {
  const out=f.c.deliverables.find(d=>d.id===f.c.tasks.find(t=>t.id===step).outputs[0]).path;
  const file=path.join(f.project,out);await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,content+'\n');return file;
}
async function submit(f,step,started,result='ok',extra={}) {
  return engine.submit(f.project,f.id,step,{runId:started.runId,executor:'codex-native',reference:'SYNTHETIC local fixture execution in '+f.project,result,...extra});
}
async function finish(f,step,extra={}) {
  const started=await engine.begin(f.project,f.id,step);await emit(f,step);await submit(f,step,started,'ok',extra);return engine.verify(f.project,f.id,step);
}

await test('unapproved-begin','Reject formal begin before approval',async()=>{const f=await fixture('unapproved');await assert.rejects(engine.begin(f.project,f.id,'a'),/approval/i);return {rejected:true};});
await test('wrong-approval-binding','Reject approval bound to another digest',async()=>{const f=await fixture('bad-approval');await assert.rejects(engine.recordDecision(f.project,f.id,{actor:'user',decision:'approve',taskId:f.id,revision:1,digest:'wrong',message:'SYNTHETIC',source:'SYNTHETIC'}),/different/);return {rejected:true};});
await test('dependency-block','Reject dependent B before verified A',async()=>{const f=await fixture('dependency');await approve(f);await assert.rejects(engine.begin(f.project,f.id,'b'),/Dependencies/);return {rejected:true};});
await test('normal-two-stage-chain','Verify A then B; whole task becomes verified',async()=>{const f=await fixture('normal');await approve(f);const a=await finish(f,'a');assert.equal(a.taskStatus,'verified');const ctx=await engine.taskContext(f.project,f.id,'b');assert.equal(ctx.canBegin,true);assert.equal(ctx.dependencies[0].status,'verified');assert.equal(ctx.files.length,1);assert.ok(!ctx.files.some(x=>x.path.endsWith('a.md')));const b=await finish(f,'b');assert.equal(b.phase,'verified');return {phase:b.phase,selectedFiles:ctx.files.map(x=>path.basename(x.path)),approvalExcerpt:ctx.review.approval.messageExcerpt};});
await test('pending-not-verified','Receipt ok remains pending acceptance; B stays blocked',async()=>{const f=await fixture('pending');await approve(f);const r=await engine.begin(f.project,f.id,'a');await emit(f,'a');const s=await submit(f,'a',r);assert.equal(s.phase,'pending_acceptance');await assert.rejects(engine.begin(f.project,f.id,'b'),/Dependencies/);return {phase:s.phase};});
await test('duplicate-begin','Reject another begin for active task',async()=>{const f=await fixture('duplicate');await approve(f);await engine.begin(f.project,f.id,'a');await assert.rejects(engine.begin(f.project,f.id,'a'),/cannot begin|active|executing/i);return {rejected:true};});
await test('writer-serialization','Reject unrelated writer while A executes',async()=>{const f=await fixture('writers');f.c.tasks[1].dependsOn=[];f.c.revision=2;await writeJson(path.join(f.directory,'contract.json'),f.c);await engine.render(f.project,f.id);f.review=await engine.prepareReview(f.project,f.id);await approve(f);await engine.begin(f.project,f.id,'a');await assert.rejects(engine.begin(f.project,f.id,'b'),/Another writing task/);return {rejected:true};});
await test('failed-retry-negative','Failed execution can retry with new run ID and preserve negative outcome',async()=>{const f=await fixture('retry',{two:false});await approve(f);const a=await engine.begin(f.project,f.id,'a');await submit(f,'a',a,'failed');const b=await engine.begin(f.project,f.id,'a');assert.notEqual(a.runId,b.runId);await emit(f,'a');await submit(f,'a',b,'ok',{outcome:'negative'});const v=await engine.verify(f.project,f.id,'a');assert.equal(v.taskStatus,'verified');assert.equal(v.outcome,'negative');return {status:v.taskStatus,outcome:v.outcome,newRun:true};});
await test('resume-original-run','An active original run survives status/context and can submit',async()=>{const f=await fixture('resume',{two:false});await approve(f);const a=await engine.begin(f.project,f.id,'a');const stateBytes=await fs.readFile(path.join(f.directory,'state.json'));const st=await engine.status(f.project,f.id);const ctx=await engine.taskContext(f.project,f.id,'a');assert.equal(st.tasks.a.runId,a.runId);assert.equal(ctx.canBegin,false);assert.deepEqual(await fs.readFile(path.join(f.directory,'state.json')),stateBytes);await emit(f,'a');const submitted=await submit(f,'a',a);assert.equal(submitted.phase,'pending_acceptance');return {originalRunPreserved:true,statusReadOnly:st.persisted===false};});
