await test('review-required','Semantic review criterion needs evidence record',async()=>{const f=await fixture('semantic-review',{two:false,acceptance:[{id:'semantic',type:'review',description:'Synthetic reviewer must supply traceable evidence'}]});await approve(f);const a=await engine.begin(f.project,f.id,'a');await emit(f,'a');await submit(f,'a',a);await assert.rejects(engine.verify(f.project,f.id,'a'),/traceable evidence/);const v=await engine.verify(f.project,f.id,'a',{semantic:{verdict:'pass',reviewer:'SYNTHETIC test reviewer',source:'SYNTHETIC evidence only',rationale:'Exercise record checking, not real semantic validity',files:['out/a.txt'],independence:'not established'}});assert.equal(v.taskStatus,'verified');return {missingRecordRejected:true,recordAccepted:true,independence:v.checks[0].independenceClaim};});
