await test('active-review-guard','Repeat review preserves active identity and approval',async()=>{const f=await fixture('active-review',{two:false});await approve(f);const r=await engine.begin(f.project,f.id,'a');const before=await engine.status(f.project,f.id);await assert.rejects(engine.prepareReview(f.project,f.id),/active|executing/i);const after=await engine.status(f.project,f.id);assert.equal(after.tasks.a.runId,r.runId);assert.equal(after.approval.digest,before.approval.digest);await assert.rejects(engine.begin(f.project,f.id,'a'),/active|executing|cannot begin/i);return {runPreserved:true};});
