await test('stale-active-closure','Stale execution blocks writers until factual closure, without accepting its result',async()=>{const f=await fixture('stale-active');await approve(f);await finish(f,'a');const r=await engine.begin(f.project,f.id,'b');await emit(f,'a','CHANGED');const st=await engine.status(f.project,f.id);assert.equal(st.tasks.b.status,'stale');await assert.rejects(engine.begin(f.project,f.id,'a'),/active|executing/i);await assert.rejects(engine.submit(f.project,f.id,'b',{runId:'unknown',executor:'codex-native',reference:'SYNTHETIC',result:'ok'}),/matching|active/i);const ended=await submit(f,'b',r);assert.equal(ended.phase,'stale');await assert.rejects(engine.verify(f.project,f.id,'b'),/pending|approved/i);const next=await engine.begin(f.project,f.id,'a');assert.notEqual(next.runId,r.runId);return {closed:true,resultStillStale:true};});
await test('invalid-approval-closure','An original run may close after approval invalidation without restoring approval',async()=>{const f=await fixture('invalid-close',{two:false});await approve(f);const r=await engine.begin(f.project,f.id,'a');await fs.appendFile(path.join(f.project,'input.txt'),'CHANGED');assert.equal((await engine.status(f.project,f.id)).approval,null);const ended=await submit(f,'a',r);assert.equal(ended.phase,'stale');assert.equal((await engine.status(f.project,f.id)).approval,null);const beforeReplay=await engine.status(f.project,f.id);const replay=await submit(f,'a',r);assert.equal(replay.replayed,true);assert.equal(replay.acceptedForVerification,false);assert.equal((await engine.status(f.project,f.id)).events.filter(e=>e.type==='execution_receipt').length,beforeReplay.events.filter(e=>e.type==='execution_receipt').length);return {closedWithoutApproval:true,notAccepted:true,idempotentReplay:true};});
async function legacyState(f,events,tasks){const file=path.join(f.directory,'state.json');const state=await readJson(file);delete state.activeExecutions;delete state.executionBlockers;state.events=events;state.tasks=tasks;await writeJson(file,state);return file;}
await test('legacy-orphan-run','Old review-reset task maps cannot hide an unclosed begin',async()=>{const f=await fixture('legacy-orphan',{two:false});await approve(f);const r=await engine.begin(f.project,f.id,'a');const st=await readJson(path.join(f.directory,'state.json'));const file=await legacyState(f,st.events,{a:{status:'todo'}});const before=await digest(file);await assert.rejects(engine.begin(f.project,f.id,'a'),/active|executing/i);const ctx=await engine.taskContext(f.project,f.id,'a');assert.equal(ctx.canBegin,false);await submit(f,'a',r,'failed');await engine.begin(f.project,f.id,'a');return {orphanBlockedAndClosed:true,before};});
await test('legacy-ambiguous-events','Ambiguous step-only receipt cannot guess which old run ended',async()=>{const f=await fixture('legacy-ambiguous',{two:false});await approve(f);const now=new Date().toISOString();const events=[{type:'begin',step:'a',runId:'old-one',at:now},{type:'begin',step:'a',runId:'old-two',at:now},{type:'execution_receipt',step:'a',result:'ok',reference:'SYNTHETIC ambiguous old receipt',at:now}];const file=await legacyState(f,events,{a:{status:'todo'}});const before=await digest(file);const st=await engine.status(f.project,f.id);const ctx=await engine.taskContext(f.project,f.id,'a');assert.equal(await digest(file),before);assert.equal(ctx.canBegin,false);assert.ok(Array.isArray(st.activeExecutions),'Derived active identities are missing');assert.equal(st.activeExecutions.length,2);await assert.rejects(engine.begin(f.project,f.id,'a'),/active|executing|ambiguous/i);await engine.submit(f.project,f.id,'a',{runId:'old-one',executor:'codex-native',reference:'SYNTHETIC observed old-one ended',result:'failed'});await assert.rejects(engine.begin(f.project,f.id,'a'),/active|executing|ambiguous/i);await engine.submit(f.project,f.id,'a',{runId:'old-two',executor:'codex-native',reference:'SYNTHETIC observed old-two ended',result:'failed'});await engine.begin(f.project,f.id,'a');return {readOnly:true,ambiguousRunsClosedExplicitly:true};});
