await test('publication-dual-failure','Publication keeps original failure and cleanup failure with actual publication state',async()=>{
 const f=await fixture('publish-dual',{two:false});await approve(f);const run=await engine.begin(f.project,f.id,'a'),value=payload(f,run),final=path.join(f.directory,'receipt-'+run.runId+'.json');const oldOpen=fs.open,oldUnlink=fs.unlink;let writeHit=false,cleanupHit=false;
 try{fs.open=async function(file,...a){const h=await oldOpen.call(this,file,...a);if(!String(file).startsWith(final+'.'))return h;return wrapHandle(h,{writeFile:async()=>{writeHit=true;throw new Error('SYNTHETIC primary write failure');}});};fs.unlink=async function(file,...a){if(String(file).startsWith(final+'.')){cleanupHit=true;throw new Error('SYNTHETIC secondary cleanup failure');}return oldUnlink.call(this,file,...a);};await assert.rejects(engine.submit(f.project,f.id,'a',value),e=>{assert.match(e.message,/primary write/);assert.match(e.message,/secondary cleanup/);assert.equal(e.receiptPublished,false);return true;});}finally{fs.open=oldOpen;fs.unlink=oldUnlink;}
 assert.equal(writeHit,true);assert.equal(cleanupHit,true);await assert.rejects(fs.stat(final),{code:'ENOENT'});assert.equal((await engine.status(f.project,f.id)).activeExecutions[0].runId,run.runId);await engine.submit(f.project,f.id,'a',value);return {bothErrorsPreserved:true};
});
