const artifactHelper=path.join(source,'scripts/tests/helpers/artifact-example.mjs');
async function artifactExample(layout,variant='complete'){
 const f=await fixture('example-'+layout+'-'+variant,{two:false});
 assert.ok(key(f.directory).startsWith(key(root)+path.sep));await fs.unlink(path.join(f.directory,'phases/a.md'));
 f.c.domain='software';f.c.revision++;await fs.writeFile(path.join(f.project,'raw.json'),'[1,2,3]\n');f.c.inputs=[{source:'SYNTHETIC fixed raw integers, not real research observations',path:'raw.json'}];
 const code=layout==='members'?[{id:'prepare-code',path:'code/prepare.mjs'},{id:'analysis-code',path:'code/analyze.mjs'},{id:'analysis-config',path:'config/analysis.json'}]:[{id:'code-bundle',path:'packages/code.zip'}];
 f.c.deliverables=[...code,{id:'clean-data',path:'data/clean.csv'},{id:'analysis-result',path:'results/summary.json'}];
 const criterion=mode=>({id:mode,type:'command',description:'SYNTHETIC verify actual '+mode+' against independently fixed values and members',command:process.execPath,args:[artifactHelper,mode,f.project,layout],timeoutMs:15000});
 f.c.tasks=[{id:'code',title:'Produce executable code and config before any consumption',dependsOn:[],outputs:code.map(x=>x.id),acceptance:[criterion('verify-code')]},{id:'data',title:'Consume verified code and create actual synthetic data',dependsOn:['code'],outputs:['clean-data'],acceptance:[criterion('verify-data')]},{id:'analysis',title:'Consume verified code and data and produce actual numerical result',dependsOn:['code','data'],outputs:['analysis-result'],acceptance:[criterion('verify-analysis')]}];
 f.c.contextFiles=f.c.tasks.map(t=>({path:'phases/'+t.id+'.md',kind:'phase',tasks:[t.id],purpose:t.title,loadWhen:'Only after context selects '+t.id}));await writeJson(path.join(f.directory,'contract.json'),f.c);
 const refs=command(['refs','--project',f.project,'--id',f.id]);assert.equal(refs.code,0,refs.stderr);const mapping=JSON.parse(refs.stdout);
 for(const d of mapping.documents.filter(x=>x.path!=='HARNESS.md')){await fs.mkdir(path.dirname(d.file),{recursive:true});await fs.writeFile(d.file,`# SYNTHETIC ${d.path}\n\nResume master/recovery then context. Consume this phase only after selection.\n\nInput: ${d.inputs[0].absoluteMarkdown}\n\nMethod: code task creates actual modules/config ${layout==='archive'?'inside a real code.zip with checked fixed members':'as individually declared member files'}; data consumes verified code; analysis consumes verified code and data.\n\nOutputs (计划产物): ${d.deliverables.map(x=>x.markdown).join(', ')}\n\nAcceptance: actual command checks member contents, data rows and sum=12; failure blocks dependencies and preserves evidence.\n\nRecovery: inspect original run and report; do not clear history.\n`);}
 const prepared=command(['prepare-review','--project',f.project,'--id',f.id]);assert.equal(prepared.code,0,prepared.stderr+' '+prepared.stdout);const p=JSON.parse(prepared.stdout);assert.equal(p.pathCheck.ok,true);f.review=p.review;await approve(f);
 const run=(mode)=>{const r=spawnSync(process.execPath,[artifactHelper,mode,f.project,layout,variant],{cwd:f.project,encoding:'utf8',timeout:15000,windowsHide:true,shell:false});assert.equal(r.status,0,r.stderr);return r;};
 let started=await engine.begin(f.project,f.id,'code');run('build-code');await submit(f,'code',started);
 if(variant==='missing'){await assert.rejects(engine.verify(f.project,f.id,'code'),/exit/);await assert.rejects(engine.begin(f.project,f.id,'data'),/Dependencies/);return {f,missingRejected:true};}
 await engine.verify(f.project,f.id,'code');for(const [step,mode]of [['data','prepare'],['analysis','analyze']]){started=await engine.begin(f.project,f.id,step);run(mode);await submit(f,step,started);await engine.verify(f.project,f.id,step);}
 assert.equal((await engine.status(f.project,f.id)).phase,'verified');assert.deepEqual(JSON.parse(await fs.readFile(path.join(f.project,'results/summary.json'),'utf8')),{sum:12});
 const file=path.join(f.project,layout==='members'?'code/prepare.mjs':'packages/code.zip');await fs.appendFile(file,'\nSYNTHETIC changed version');const s=await engine.status(f.project,f.id);for(const step of ['code','data','analysis'])assert.equal(s.tasks[step].status,'stale');return {f,sum:12,downstreamInvalidated:true};
}
