 f.c.revision++;await writeJson(path.join(f.directory,'contract.json'),f.c);
 if(upstream&&layered){const r=command(['refs','--project',f.project,'--id',f.id]);assert.equal(r.code,0,r.stderr);const doc=JSON.parse(r.stdout).documents.find(d=>d.path==='phases/c.md');await fs.writeFile(doc.file,`# SYNTHETIC C\n\nResume with master/recovery then context. Input: ${doc.inputs[0].absoluteMarkdown}\n\nMethod: produce deterministic C. Output: ${doc.deliverables.find(d=>d.id==='out-c').markdown}\n\nAcceptance: check C. Failure: retain evidence. Handoff: only verified C.\n`);}
 await engine.render(f.project,f.id);f.review=await engine.prepareReview(f.project,f.id);await approve(f);
