 f.before=await engine.status(f.project,f.id);f.receiptBytes=await fs.readFile(f.before.tasks.a.receipt.path);
 f.reviews={'review':{verdict:'pass',reviewer:'SYNTHETIC local test',source:'SYNTHETIC fixture',rationale:'Synthetic evidence only',files:['out/a.txt']}};
 return f;
